const d = $input.first().json;
const approveUrl = $execution.resumeUrl + '?outcome=approved';
const rejectUrl  = $execution.resumeUrl + '?outcome=rejected';

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><style>
  body{font-family:Arial,sans-serif;margin:0;padding:0;background:#f1f5f9}
  .wrap{max-width:660px;margin:30px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.08)}
  .hdr{background:#1e293b;padding:24px 32px;color:#fff}
  .hdr h1{margin:0;font-size:20px}
  .hdr p{margin:6px 0 0;color:#94a3b8;font-size:13px}
  .body{padding:32px}
  .badge{display:inline-block;padding:4px 12px;border-radius:20px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:16px}
  .badge.order_issue{background:#fef9c3;color:#854d0e}
  .badge.refund_request{background:#fee2e2;color:#991b1b}
  .badge.product_help{background:#dbeafe;color:#1e40af}
  .badge.delivery{background:#dcfce7;color:#166534}
  .badge.general{background:#f3f4f6;color:#374151}
  .section{background:#f8fafc;border-radius:8px;padding:20px;margin-bottom:20px}
  .section h3{margin:0 0 10px;font-size:14px;color:#64748b;text-transform:uppercase;letter-spacing:.5px}
  .section p{margin:0;color:#1e293b;font-size:15px;white-space:pre-wrap;line-height:1.6}
  .actions{display:flex;gap:12px;margin-top:24px}
  .btn{display:inline-block;padding:14px 28px;border-radius:8px;text-decoration:none;font-weight:700;font-size:15px;text-align:center}
  .approve{background:#16a34a;color:#fff}
  .reject{background:#dc2626;color:#fff}
  .meta{font-size:12px;color:#94a3b8;margin-top:20px}
</style></head>
<body>
  <div class="wrap">
    <div class="hdr">
      <h1>Support Reply — Awaiting Approval</h1>
      <p>Ticket ${d.ticket_id} &bull; ${d.from_email}</p>
    </div>
    <div class="body">
      <span class="badge ${d.intent || 'general'}">${(d.intent||'general').replace('_',' ')}</span>
      <div class="section">
        <h3>Customer Email</h3>
        <p><strong>From:</strong> ${d.from_name} &lt;${d.from_email}&gt;<br><strong>Subject:</strong> ${d.subject}</p>
        <br>
        <p>${d.body_text}</p>
      </div>
      <div class="section">
        <h3>AI Draft Reply</h3>
        <p>${d.ai_draft}</p>
      </div>
      <div class="actions">
        <a href="${approveUrl}" class="btn approve">Approve &amp; Send</a>
        <a href="${rejectUrl}" class="btn reject">Reject</a>
      </div>
      <p class="meta">This approval link expires in 24 hours. Ticket: ${d.ticket_id}</p>
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    ...d,
    approval_email_html: html,
    approve_url: approveUrl,
    reject_url:  rejectUrl
  }
}];
